import "sort"
import "strings"

func isAnagram(s string, t string) bool {
	if len(s) != len(t) {
		return false
	}
	sChars := strings.Split(s, "")
	tChars := strings.Split(t, "")
	sort.Strings(sChars)
	sort.Strings(tChars)
	return strings.Join(sChars, "") == strings.Join(tChars, "")
}

